// ===============================================================================
// DAEMIND SRE - PARSER CANÔNICO DA NUVEMSHOP
// ===============================================================================
const crypto = require('crypto');
const body = $json.body || $json;

const customer = body.customer || {};
let rawPhone = (customer.phone || body.billing_phone || body.shipping_phone || '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const clienteNome = (customer.name || body.billing_name || 'Cliente Nuvemshop').trim();
const clienteEmail = (customer.email || body.email || '').trim().toLowerCase();
const clienteDoc = (customer.identification || body.billing_identification || '').toString().replace(/\D/g, '');

const numeroPedido = parseInt(body.number || body.id || Date.now(), 10);
const valorTotal = parseFloat(body.total || 0);
const valorFrete = parseFloat(body.shipping_cost_customer || body.shipping_cost_owner || 0);
const paymentStatus = (body.payment_status || 'pending').toLowerCase();
const shippingStatus = (body.shipping_status || 'unpacked').toLowerCase();

let statusOperacional = 'Pendente';
if (paymentStatus === 'paid') {
  statusOperacional = 'Pago';
} else if (paymentStatus === 'voided' || paymentStatus === 'refunded') {
  statusOperacional = 'Cancelado';
}

if (shippingStatus === 'shipped') {
  statusOperacional = 'Enviado';
}

const produtos = (body.products || []).map(p => ({
  produto_nome: p.name || 'Produto',
  sku: p.sku || 'NUVEM_SKU',
  quantidade: parseInt(p.quantity || 1, 10),
  preco_venda: parseFloat(p.price || 0)
}));

const dedupHash = crypto.createHash('sha256').update(`nuvemshop_${numeroPedido}_${statusOperacional}_${valorTotal}`).digest('hex');

return [{
  json: {
    dedup_hash: dedupHash,
    numero_pedido: numeroPedido,
    cliente_nome: clienteNome,
    cliente_email: clienteEmail,
    cliente_whatsapp: rawPhone,
    cliente_doc: clienteDoc,
    valor_total: valorTotal,
    valor_frete: valorFrete,
    status_operacional: statusOperacional,
    produtos: produtos
  }
}];
